<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><section class="upload panel"><h2>Upload image</h2><form method="post" enctype="multipart/form-data" action="<?= site_url('admin/media') ?>"><?= csrf_field() ?><label>Image<input type="file" name="file" accept="image/*" required></label><label>Alt text<input name="alt_text"></label><button class="admin-button">Upload</button></form></section><section class="media-grid"><?php foreach ($media as $item): ?><article><img src="<?= base_url($item['path']) ?>" alt="<?= esc($item['alt_text']) ?>"><p><?= esc($item['filename']) ?></p><code><?= esc($item['path']) ?></code><form method="post" action="<?= site_url('admin/media/' . $item['id'] . '/delete') ?>" onsubmit="return confirm('Delete this image?')"><?= csrf_field() ?><button>Delete</button></form></article><?php endforeach ?></section><?= $this->endSection() ?>
